export function authenticate(token: string) {
  return token === "demo-token";
}

import { authenticate } from "./auth";
import { checkout } from "./checkout";
export function placeOrder(token: string, stock: number) {
  const approved = authenticate(token);
  return checkout(stock, approved);
}

export function checkout(stock: number, approved: boolean) {
  if (stock < 1) return "sold out";
  if (!approved) return "payment declined";
  stock--;
  return "order confirmed";
}

export const transitions = {
  "queued:start": "running",
  "running:complete": "done",
  "running:fail": "failed",
  "failed:retry": "queued"
} as const;
export const terminal = new Set(["done"]);

export function calculateTotal(price: number, quantity: number) {
  const subtotal = price * quantity;
  const total = subtotal * 1.1;
  return total;
}
